------------ lifeCycle ------------


function QuestBtnGroup:CleanProperties()
    self.questIdList = nil
    self.curSelectedBtn = nil
    self.callback = nil
    self.curSelectedQuestId = nil
    self.activityPrefabId = nil
    self.activityContentId = nil
end

function QuestBtnGroup:Refresh(activityPrefabId, activityContentId, bossTypeId, questId)
    self.activityPrefabId = activityPrefabId
    self.activityContentId = activityContentId

    local comp = AnnihilationUtils.GetComponent(self.activityPrefabId)
    local vo = comp:GetTypeVo(bossTypeId)
    if not vo then
        return
    end
    
    if isNull(questId) or (questId < 0) then
        self.curSelectedQuestId = AnnihilationUtils.GetLastUnlockedQuestId(activityPrefabId, activityContentId, bossTypeId)
    else
        self.curSelectedQuestId = questId
    end
    
    self.questIdList = parse_strings(vo.contentLevel, ";")
    -- print("歼灭战 ", questId, #self.questIdList, self.curSelectedQuestId)
    self:RefreshLoopListView(#self.questIdList)
end

function QuestBtnGroup:RefreshLoopListView(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function QuestBtnGroup:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local luaIndex = index + 1

    local cell = loopListView:NewListViewItem(LoopListViewCellName)
    local LB_cell = GetLuaBehaviour(cell.gameObject, BtnCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
    end
    local LT_cell = LB_cell.Env
    local questId = checkNumber(self.questIdList[luaIndex])
    LT_cell:Refresh(self.activityPrefabId, self.activityContentId, questId, luaIndex)
    LT_cell:FillSelect(false)
    LT_cell:SetClickCallback(Bind(self, self.OnBtnClicked))

    -- 默认选中哪一个按钮
    if self.curSelectedQuestId == questId then
        self:OnBtnClicked(LT_cell)
    end

    return cell
end

function QuestBtnGroup:OnBtnClicked(LT_Btn)
    if isNotNull(self.curSelectedBtn) then
        self.curSelectedBtn:FillSelect(false)
    end
    self.curSelectedBtn = LT_Btn
    self.curSelectedBtn:FillSelect(true)
    self.callback(self.activityPrefabId, self.activityContentId, self.curSelectedBtn.questVo.id)
    self.curSelectedQuestId = self.curSelectedBtn.questVo.id
end

function QuestBtnGroup:SetClickCallback(callback)
    self.callback = callback
end

return QuestBtnGroup